#!/usr/bin/env node
/**
 * Verify the committed font payload matches `fonts/manifest.json`.
 *
 * The woff2 files are generated by `npm run fonts` and committed; this check makes
 * sure a stale edit (or a missing license file) fails CI instead of shipping.
 */
import { createHash } from "node:crypto";
import { existsSync, readFileSync } from "node:fs";
import path from "node:path";
import process from "node:process";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const FONT_DIR = path.join(ROOT, "fonts");
const manifest = JSON.parse(readFileSync(path.join(FONT_DIR, "manifest.json"), "utf8"));

const failures = [];
const sha256 = (file) => createHash("sha256").update(readFileSync(file)).digest("hex");

for (const font of manifest.fonts ?? []) {
  for (const [label, file, size, hash] of [
    ["font", font.file, font.bytes, font.sha256],
    ["preview", font.previewFile, font.previewBytes, font.previewSha256],
  ]) {
    const filePath = path.join(FONT_DIR, file);
    if (!existsSync(filePath)) {
      failures.push(`${font.id}: ${label} ${file} is missing`);
      continue;
    }
    const bytes = readFileSync(filePath);
    if (bytes.length !== size) failures.push(`${font.id}: ${label} ${file} is ${bytes.length} bytes, manifest says ${size}`);
    if (sha256(filePath) !== hash) failures.push(`${font.id}: ${label} ${file} sha256 does not match the manifest`);
    if (bytes.subarray(0, 4).toString("latin1") !== "wOF2") failures.push(`${font.id}: ${label} ${file} is not a woff2 file`);
  }
  const licensePath = path.join(FONT_DIR, "licenses", font.license?.file ?? "");
  if (font.license?.file === undefined || !existsSync(licensePath)) {
    failures.push(`${font.id}: license ${font.license?.file ?? "(unset)"} is missing`);
  }
}

if ((manifest.fonts ?? []).length === 0) failures.push("manifest has no fonts");
if (manifest.licenses?.length !== new Set((manifest.fonts ?? []).map((font) => font.license?.file)).size) {
  failures.push("manifest licenses list does not cover every font");
}
// A typography table that loses the scale tokens would silently disable the slider.
const tokens = JSON.parse(readFileSync(path.join(ROOT, "src", "typography.tokens.json"), "utf8"));
for (const name of ["--dsw-font-base-16", "--dsw-font-base-16-font-size", "--dsw-font-s-14"]) {
  if (typeof tokens[name] !== "string") failures.push(`typography.tokens.json misses ${name}`);
}

if (failures.length > 0) {
  console.error(failures.join("\n"));
  process.exit(1);
}
const total = (manifest.fonts ?? []).reduce((sum, font) => sum + font.bytes + font.previewBytes, 0);
console.log(
  `fonts OK: ${manifest.fonts.length} faces, ${(total / 1024 / 1024).toFixed(2)} MB, ` +
    `${Object.keys(tokens).length} scale tokens`,
);
